describe('Request ID Middleware with trustIncoming', () => {
  const app = new Hono()
  app.use('/default', requestId({ generator: () => 'generated-id' }))
  app.use('/trusted', requestId({ generator: () => 'generated-id', trustIncoming: true }))
  app.use('/untrusted', requestId({ generator: () => 'generated-id', trustIncoming: false }))
  app.get('/default', (c) => c.text(c.get('requestId') ?? 'No Request ID'))
  app.get('/trusted', (c) => c.text(c.get('requestId') ?? 'No Request ID'))
  app.get('/untrusted', (c) => c.text(c.get('requestId') ?? 'No Request ID'))

  it('Should trust incoming request id by default', async () => {
    const res = await app.request('http://localhost/default', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('incoming-id')
    expect(await res.text()).toBe('incoming-id')
  })

  it('Should trust incoming request id when trustIncoming is true', async () => {
    const res = await app.request('http://localhost/trusted', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('incoming-id')
    expect(await res.text()).toBe('incoming-id')
  })

  it('Should ignore incoming request id when trustIncoming is false', async () => {
    const res = await app.request('http://localhost/untrusted', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('generated-id')
    expect(await res.text()).toBe('generated-id')
  })

  it('Should generate request id when no header is sent and trustIncoming is false', async () => {
    const res = await app.request('http://localhost/untrusted')
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('generated-id')
    expect(await res.text()).toBe('generated-id')
  })
})
EOF
